"""Native joint-position controller for this frozen StockingBreakfastFoods scene."""
import numpy as np
import mujoco
from scipy.spatial.transform import Rotation
import casa_tool
from PIL import Image

class Controller:
    def __init__(self, s):
        self.s = s
        self.m = s.model
        self.d = s.data
        self.ikdata = mujoco.MjData(self.m)
        self.qidx = np.array([self.m.joint(f'robot0_joint{i}').qposadr[0] for i in range(1,8)])
        self.vidx = np.array([self.m.joint(f'robot0_joint{i}').dofadr[0] for i in range(1,8)])
        self.limits = np.array([self.m.joint(f'robot0_joint{i}').range for i in range(1,8)])
        self.site = self.m.site('gripper0_right_grip_site').id
        self.grip = -1
        self.q = self.d.qpos[self.qidx].copy()
        self.down = np.diag([-1.,1.,-1.])

    def pose(self):
        return self.d.site_xpos[self.site].copy(), self.d.site_xmat[self.site].reshape(3,3).copy()

    def obj(self, name):
        return self.d.xpos[self.s.env.obj_body_id[name]].copy()

    def ik(self, pos, rot, seed=None, iterations=120):
        x = self.ikdata
        x.qpos[:] = self.d.qpos
        q = self.q.copy() if seed is None else np.array(seed).copy()
        jp = np.zeros((3,self.m.nv)); jr=np.zeros((3,self.m.nv))
        for i in range(iterations):
            x.qpos[self.qidx] = q
            mujoco.mj_kinematics(self.m,x)
            mujoco.mj_comPos(self.m,x)
            p = x.site_xpos[self.site]
            r = x.site_xmat[self.site].reshape(3,3)
            err=np.r_[np.asarray(pos)-p, Rotation.from_matrix(rot@r.T).as_rotvec()]
            if np.linalg.norm(err[:3])<0.0003 and np.linalg.norm(err[3:])<0.002:
                break
            mujoco.mj_jacSite(self.m,x,jp,jr,self.site)
            J=np.r_[jp[:,self.vidx],jr[:,self.vidx]]
            lam=0.0001
            dq=J.T@np.linalg.solve(J@J.T+lam*np.eye(6),err)
            dq=np.clip(dq,-.12,.12)
            q=np.clip(q+dq,self.limits[:,0]+.01,self.limits[:,1]-.01)
        return q, np.linalg.norm(err[:3]), np.linalg.norm(err[3:])

    def step(self, q=None, base=None, torso=0):
        if q is not None: self.q=np.asarray(q).copy()
        a=np.r_[self.q,self.grip, [0,0,0] if base is None else base,torso,-1.]
        return self.s.step(a)

    def wait(self, n=10):
        for _ in range(n): self.step()

    def move(self, pos, rot=None, n=None, speed=.008, settle=10):
        p0,r0=self.pose()
        pos=np.asarray(pos,float)
        if rot is None: rot=self.down
        delta=Rotation.from_matrix(rot@r0.T).as_rotvec()
        if n is None: n=max(20,int(np.ceil(np.linalg.norm(pos-p0)/speed)),int(np.ceil(np.linalg.norm(delta)/.04)))
        worst=0
        for t in range(1,n+1):
            a=t/n; a=a*a*(3-2*a)
            p=p0+(pos-p0)*a
            r=Rotation.from_rotvec(delta*a).as_matrix()@r0
            q,ep,er=self.ik(p,r)
            worst=max(worst,ep)
            self.step(q)
        self.wait(settle)
        print('MOVE', len(self.s.actions), 'target',pos,'actual',self.pose()[0],'ikerr',round(worst,4),flush=True)

    def close(self,n=20):
        self.grip=1; self.wait(n)
        print('CLOSE',self.pose()[0], 'obj1',self.obj('obj1'),'obj2',self.obj('obj2'),flush=True)

    def open(self,n=20):
        self.grip=-1;self.wait(n)

    def snap(self,name):
        Image.fromarray(self.s.render_grid()).save('/app/output/'+name+'.png')

    def status(self):
        from robocasa.utils import object_utils as OU
        print('STATUS',self.s.check(),'eef',self.pose()[0], 'objects',self.obj('obj1'),self.obj('obj2'), 'inside',[OU.obj_inside_of(self.s.env,'obj1',self.s.env.cab1),OU.obj_inside_of(self.s.env,'obj2',self.s.env.cab2)],flush=True)


def main():
    s=casa_tool.Session('/app/instance.npz')
    c=Controller(s)
    # Controller sequence filled in after geometric inspection.
    c.wait(1)
    s.save_trajectory()

if __name__ == '__main__':
    main()
